inline std::tuple<int, int, std::vector<int> > Get_Num_of_z_pT_Bins_w_Migrations(int Q2_y_Bin_Num_In){
    if((Q2_y_Bin_Num_In < 1) || (Q2_y_Bin_Num_In > kMaxQ2y)){
        std::vector<int> migration;
        for(int i = 1; i < 55; ++i){ migration.push_back(i); }
        return std::make_tuple(1, 1, migration);
    }
    const int total = kZptTotal[Q2_y_Bin_Num_In];
    const int last = kZptLast[Q2_y_Bin_Num_In];
    std::vector<int> migration;
    // Return [2] is unused by Dedicated_5D_Unfold (skip_condition is table-driven).
    return std::make_tuple(total, last, migration);
}

inline bool skip_condition_z_pT_bins(int Q2_Y_BIN, int Z_PT_BIN){
    if((Q2_Y_BIN < 1) || (Q2_Y_BIN > kMaxQ2y) || (Z_PT_BIN < 0) || (Z_PT_BIN > kMaxZpT)){
        return false;
    }
    return kSkipZpT[Q2_Y_BIN][Z_PT_BIN] != 0;
}

inline ConvertResult Convert_All_Kinematic_Bins(const std::string& Start_Bins_Name, const std::string& End_Bins_Name){
    std::string check = Start_Bins_Name + " -> " + End_Bins_Name;
    auto replace_all = [](std::string& s, const std::string& from, const std::string& to){
        size_t pos = 0;
        while((pos = s.find(from, pos)) != std::string::npos){
            s.replace(pos, from.size(), to);
            pos += to.size();
        }
    };
    replace_all(check, "3D_Bins", "MultiDim_z_pT_phi_h");
    replace_all(check, "5D_Bins", "MultiDim_Q2_y_z_pT_phi_h");
    ConvertResult result;
    const std::string arrow = " -> ";
    const size_t split = check.find(arrow);
    if(split == std::string::npos){ return result; }
    const std::string left = check.substr(0, split);
    const std::string right = check.substr(split + arrow.size());
    if(right == "MultiDim_Q2_y_z_pT_phi_h"){
        // "Q2-y=Q, z-pT=Z"
        int q2y = 0;
        int zpt = 0;
        if(std::sscanf(left.c_str(), "Q2-y=%d, z-pT=%d", &q2y, &zpt) == 2){
            if((q2y >= 1) && (q2y <= kMaxQ2y) && (zpt >= 0) && (zpt <= kMaxZpT) && (kStartSlot[q2y][zpt] > 0)){
                result.ok = true;
                result.value = kStartSlot[q2y][zpt];
            }
        }
        return result;
    }
    if((right == "Q2-y") || (right == "z-pT")){
        int slot = 0;
        if(std::sscanf(left.c_str(), "MultiDim_Q2_y_z_pT_phi_h=%d", &slot) == 1){
            if((slot >= 0) && (slot <= kTotalHistBins) && (kHasReverseSlot[slot] != 0)){
                result.ok = true;
                result.value = (right == "Q2-y") ? kReverseQ2y[slot] : kReverseZpT[slot];
            }
        }
        return result;
    }
    return result;
}

